-- Synthetic users, keys, jobs and budget are rolled back. No HTTP or exchange action.
begin;
do $$declare u uuid='fa111111-1111-4111-8111-111111111111';v uuid='fa222222-2222-4222-8222-222222222222';j jsonb;r jsonb;lid uuid;jid uuid;other uuid;sid uuid;fn regprocedure;begin
 insert into auth.users(id,aud,role,email) values(u,'authenticated','authenticated','rea-codex-test-1@example.invalid'),(v,'authenticated','authenticated','rea-codex-test-2@example.invalid');
 insert into rea.bot_settings(user_id,state) select u,state from rea.bot_settings limit 1;
 insert into rea.bot_settings(user_id,state) select v,state from rea.bot_settings limit 1;
 insert into rea.live_accounts(user_id,state,latest) select u,state,latest from rea.live_accounts limit 1;
 if not found then raise exception 'NEEDS_EXISTING_LIVE_SNAPSHOT';end if;
 if (public.rea_codex_view(u)->>'configured')::boolean then raise exception 'PHANTOM_KEY';end if;
 if public.rea_codex_claim() is not null then raise exception 'UNCONFIGURED_WORK';end if;
 for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'rea_codex_%' loop
  if has_function_privilege('authenticated',fn,'EXECUTE') or has_function_privilege('anon',fn,'EXECUTE') then raise exception 'RPC_EXPOSED: %',fn;end if;
 end loop;
 if has_table_privilege('authenticated','rea.codex_settings','SELECT') or has_table_privilege('anon','rea.codex_jobs','SELECT') then raise exception 'CODEX_TABLE_EXPOSED';end if;
 begin perform public.rea_codex_request(u,'premature');raise exception 'KEYLESS_REQUEST_ACCEPTED';exception when others then if sqlerrm='KEYLESS_REQUEST_ACCEPTED' then raise;end if;end;
 r=public.rea_codex_configure(u,'sk-TEST_ONLY_SYNTHETIC_KEY_12345678901234567890',false,true);
 perform public.rea_codex_configure(v,'sk-TEST_ONLY_ANOTHER_KEY_12345678901234567890',false,true);
 if not (r->>'configured')::boolean or (r->>'enabled')::boolean or r::text like '%sk-TEST%' or r::text like '%secret_id%' then raise exception 'KEY_OR_STATE_LEAK';end if;
 select secret_id into sid from rea.codex_settings where user_id=u;
 if not exists(select 1 from vault.secrets where id=sid) then raise exception 'KEY_NOT_IN_VAULT';end if;
 perform public.rea_codex_request(u,'ตรวจพอร์ต');j=public.rea_codex_claim();jid=(j->'job'->>'id')::uuid;lid=(j->'job'->>'lease')::uuid;
 if j->>'action'<>'CREATE' or j->'job'->>'user_id'<>u::text or jid is null then raise exception 'CLAIM_FAILED: %',j;end if;
 if public.rea_codex_claim() is not null then raise exception 'DUPLICATE_CLAIM';end if;
 if (public.rea_codex_view(u)->>'dailyCalls')::integer<>1 then raise exception 'BUDGET_NOT_RESERVED';end if;
 if (public.rea_codex_view(v)->>'dailyCalls')::integer<>0 or public.rea_codex_view(v)->'jobs'<>'[]'::jsonb then raise exception 'CROSS_ACCOUNT_LEAK';end if;
 begin perform public.rea_codex_key(v,jid,lid);raise exception 'OTHER_OWNER_LOADED_KEY';exception when others then if sqlerrm='OTHER_OWNER_LOADED_KEY' then raise;end if;end;
 if public.rea_codex_key(u,jid,lid) is null then raise exception 'LEASE_CANNOT_LOAD_KEY';end if;
 if public.rea_codex_checkpoint(jid,gen_random_uuid(),'RUNNING','sess_TEST_ONLY') then raise exception 'STALE_LEASE_ACCEPTED';end if;
 begin perform public.rea_codex_request(u,'duplicate');raise exception 'PARALLEL_REQUEST_ACCEPTED';exception when others then if sqlerrm='PARALLEL_REQUEST_ACCEPTED' then raise;end if;end;
 if not public.rea_codex_checkpoint(jid,lid,'RUNNING','sess_TEST_ONLY') then raise exception 'CHECKPOINT_FAILED';end if;
 j=public.rea_codex_claim();lid=(j->'job'->>'lease')::uuid;
 if j->>'action'<>'POLL' or j->'job'->>'session_id'<>'sess_TEST_ONLY' then raise exception 'RESTART_RECREATED_SESSION';end if;
 begin perform public.rea_codex_checkpoint(jid,lid,'COMPLETED','sess_TEST_ONLY','{"provider":"OPENAI_CODEX_MANAGED_AGENT","canTrade":true,"canChangeLimits":false}');raise exception 'TRADING_RESULT_ACCEPTED';exception when others then if sqlerrm='TRADING_RESULT_ACCEPTED' then raise;end if;end;
 begin perform public.rea_codex_checkpoint(jid,lid,'RUNNING','sess_DIFFERENT');raise exception 'SESSION_MUTATED';exception when others then if sqlerrm='SESSION_MUTATED' then raise;end if;end;
 perform public.rea_codex_checkpoint(jid,lid,'COMPLETED','sess_TEST_ONLY','{"provider":"OPENAI_CODEX_MANAGED_AGENT","canTrade":false,"canChangeLimits":false,"summary":"SQL fixture only"}');
 if public.rea_codex_view(u)->'latest'->>'summary'<>'SQL fixture only' then raise exception 'RESULT_NOT_RECORDED';end if;
 begin perform public.rea_codex_request(u,'too soon');raise exception 'COOLDOWN_BYPASSED';exception when others then if sqlerrm='COOLDOWN_BYPASSED' then raise;end if;end;
 update rea.codex_settings set last_started=now()-interval '6 minutes' where user_id=u;
 update rea.codex_budget set calls=8 where user_id=u;
 begin perform public.rea_codex_request(u,'over budget');raise exception 'DAILY_LIMIT_BYPASSED';exception when others then if sqlerrm='DAILY_LIMIT_BYPASSED' then raise;end if;end;
 update rea.codex_budget set calls=1 where user_id=u;
 perform public.rea_codex_request(u,'restart create');j=public.rea_codex_claim();jid=(j->'job'->>'id')::uuid;
 update rea.codex_jobs set lease_until=now()-interval '1 minute' where id=jid;
 if public.rea_codex_claim() is not null then raise exception 'UNCERTAIN_CREATE_RETRIED';end if;
 if not exists(select 1 from rea.codex_jobs where id=jid and status='UNKNOWN') then raise exception 'UNKNOWN_NOT_LATCHED';end if;
 begin perform public.rea_codex_configure(u,'sk-TEST_ONLY_REPLACEMENT_12345678901234567890',false,true);raise exception 'UNKNOWN_KEY_ROTATION_ACCEPTED';exception when others then if sqlerrm='UNKNOWN_KEY_ROTATION_ACCEPTED' then raise;end if;end;
 begin perform public.rea_codex_resolve_unknown(u,'wrong');raise exception 'RESOLUTION_NOT_CONFIRMED';exception when others then if sqlerrm='RESOLUTION_NOT_CONFIRMED' then raise;end if;end;
 perform public.rea_codex_resolve_unknown(u,'ตรวจคำขอ Codex ที่ไม่ทราบผลแล้ว');
 if exists(select 1 from rea.codex_settings where user_id=u and (enabled or requested)) then raise exception 'RESOLUTION_ENABLED_AUTOMATION';end if;
 if (select count(*) from rea.codex_budget where user_id=u and day=(now() at time zone 'Asia/Bangkok')::date)<>1 then raise exception 'WRONG_BANGKOK_DAY';end if;
end$$;
rollback;
select 'CODEX_POSTGRES_CHECKS_PASSED_NO_HTTP_ROLLED_BACK' as result;
